const putGuardianModel = `-- name: PutGuardianModel :execrows
INSERT INTO guardian_turn_models(epoch_id,thread_id,turn_id,model_id,provider_at)
SELECT ?1,?2,?3,?4,?5
WHERE (SELECT COUNT(*) FROM guardian_turn_models m WHERE m.epoch_id=?1 AND m.thread_id=?2)<4096
 OR EXISTS(SELECT 1 FROM guardian_turn_models m WHERE m.epoch_id=?1 AND m.thread_id=?2 AND m.turn_id=?3)
ON CONFLICT(epoch_id,thread_id,turn_id) DO UPDATE SET
 conflict=1 WHERE conflict=0 AND model_id IS NOT excluded.model_id
`

type PutGuardianModelParams struct {
	EpochID    int64
	ThreadID   string
	TurnID     string
	ModelID    string
	ProviderAt time.Time
}

func (q *Queries) PutGuardianModel(ctx context.Context, arg PutGuardianModelParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, putGuardianModel,
		arg.EpochID,
		arg.ThreadID,
		arg.TurnID,
		arg.ModelID,
		arg.ProviderAt,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

